                    "sql": "CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_fact_items AS WITH CTE AS ( SELECT _airbyte_emitted_at, _airbyte_data:\"number-of-items\"::STRING AS number_of_items, _airbyte_data:\"payment-method-details\"::STRING AS payment_method_details, _airbyte_data:\"promotion-ids\"::STRING AS promotion_ids, _airbyte_data:\"purchase-order-number\"::STRING AS purchase_order_number, _airbyte_data:\"is-amazon-invoiced\"::STRING AS is_amazon_invoiced, _airbyte_data:\"order-status\"::STRING AS order_status, _airbyte_data:\"order-channel\"::STRING AS order_channel, _airbyte_data:\"amazon-order-id\"::STRING AS amazon_order_id, _airbyte_data:\"is-iba\"::STRING AS is_iba, _airbyte_data:\"item-promotion-discount\"::STRING AS item_promotion_discount, _airbyte_data:\"ship-postal-code\"::STRING AS ship_postal_code, _airbyte_data:\"merchant-order-id\"::STRING AS merchant_order_id, _airbyte_data:\"item-status\"::STRING AS item_status, _airbyte_data:\"fulfilled-by\"::STRING AS fulfilled_by, _airbyte_data:\"vat-exclusive-item-price\"::STRING AS vat_exclusive_item_price, _airbyte_data:\"last-updated-date\"::TIMESTAMP AS last_updated_date, _airbyte_data:\"currency\"::STRING AS currency, _airbyte_data:\"product-name\"::STRING AS product_name, _airbyte_data:\"sku\"::STRING AS sku, _airbyte_data:\"gift-wrap-tax\"::STRING AS gift_wrap_tax, _airbyte_data:\"is-business-order\"::STRING AS is_business_order, _airbyte_data:\"shipping-tax\"::STRING AS shipping_tax, _airbyte_data:\"quantity\"::NUMBER AS quantity, _airbyte_data:\"item-price\"::STRING AS item_price, _airbyte_data:\"fulfillment-channel\"::STRING AS fulfillment_channel, _airbyte_data:\"tax-collection-model\"::STRING AS tax_collection_model, _airbyte_data:\"purchase-date\"::TIMESTAMP AS purchase_date, _airbyte_data:\"order-invoice-type\"::STRING AS order_invoice_type, _airbyte_data:\"ioss-number\"::STRING AS ioss_number, _airbyte_data:\"item-tax\"::STRING AS item_tax, _airbyte_data:\"shipping-price\"::STRING AS shipping_price, _airbyte_data:\"tax-collection-responsible-party\"::STRING AS tax_collection_responsible_party, _airbyte_data:\"ship-city\"::STRING AS ship_city, _airbyte_data:\"vat-exclusive-shipping-price\"::STRING AS vat_exclusive_shipping_price, _airbyte_data:\"price-designation\"::STRING AS price_designation, _airbyte_data:\"vat-exclusive-giftwrap-price\"::STRING AS vat_exclusive_giftwrap_price, _airbyte_data:\"ship-state\"::STRING AS ship_state, _airbyte_data:\"ship-promotion-discount\"::STRING AS ship_promotion_discount, _airbyte_data:\"ship-country\"::STRING AS ship_country, _airbyte_data:\"asin\"::STRING AS asin, _airbyte_data:\"gift-wrap-price\"::STRING AS gift_wrap_price, _airbyte_data:\"sales-channel\"::STRING AS sales_channel, _airbyte_data:\"ship-service-level\"::STRING AS ship_service_level FROM sleepycat_db.maplemonk._airbyte_raw_Custom_Amazon_Seller_Partner_SC_AMAZON_SLP_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL qualify DENSE_RANK() OVER ( PARTITION BY _airbyte_data:\"amazon-order-id\"::STRING, _airbyte_data:\"asin\"::STRING ORDER BY TO_CHAR(_airbyte_emitted_at, \'YYYY-MM-DD HH24:00:00\') DESC ) = 1 ) SELECT \'AMAZON_SLP\' AS shop_name, amazon_order_id AS order_id, NULL AS order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, null AS line_item_id, SKU, ASIN AS product_id, currency, case when order_status in (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\',\'Shipped - Rejected by Buyer\',\'Shipped - Damaged\') then 1 else 0 end AS is_refund, ship_city AS city, ship_state AS state, product_name AS product_name, NULL AS category, order_status AS order_status, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', purchase_date:: DATETIME) AS order_timestamp, ifnull(TRY_CAST( nullif(trim(item_price),\'\') AS FLOAT),0) AS line_item_sales, ifnull(TRY_CAST( nullif(trim(shipping_price),\'\') AS FLOAT),0) AS shipping_price, ifnull(TRY_CAST( nullif(trim(QUANTITY),\'\') AS FLOAT),0) AS quantity, ifnull(TRY_CAST( nullif(trim(item_tax),\'\') AS FLOAT),0) AS tax, div0(tax,line_item_sales+tax) as tax_rate, IFNULL(TRY_CAST(NULLIF(TRIM(item_promotion_discount), \'\') AS FLOAT), 0) AS discount, div0(discount,(1-tax_rate)) AS discount_before_tax, NULL AS gross_sales_after_tax, line_item_sales - discount_before_tax AS gross_sales_before_tax, NULL AS net_sales_before_tax, line_item_sales - discount + tax AS total_sales, fulfillment_channel fulfillment_channel, \'Amazon\' AS source, NULL AS landing_utm_medium, NULL AS landing_utm_source, NULL AS landing_utm_campaign, NULL AS referring_utm_medium, NULL AS referring_utm_source, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, IFNULL(TRY_CAST(NULLIF(TRIM(shipping_tax), \'\') AS FLOAT), 0) AS shipping_tax, IFNULL(TRY_CAST(NULLIF(TRIM(ship_promotion_discount), \'\') AS FLOAT), 0) AS ship_promotion_discount, IFNULL(TRY_CAST(NULLIF(TRIM(gift_wrap_price), \'\') AS FLOAT), 0) AS gift_wrap_price, IFNULL(TRY_CAST(NULLIF(TRIM(gift_wrap_tax), \'\') AS FLOAT), 0) AS gift_wrap_tax from CTE; create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_orders_fact_items AS select * FROM SLEEPYCAT_DB.MAPLEMONK.Custom_Amazon_Seller_Partner_SC_AMAZON_SLP_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_ORDER_DATE_GENERAL ; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_fact_items_TEMP_Category as select fi.* ,upper(coalesce(p.name,fi.product_name)) as product_name_final ,coalesce(Upper(p.CATEGORY),upper(fi.category)) AS product_category ,Upper(p.sub_category) as product_sub_category ,AmazonOrdersBuyer.Buyer_email ,AmazonOrdersBuyer.Buyer_name ,AmazonOrdersBuyer.Recipient_Name ,p.skucode common_sku_code from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_fact_items fi left join (select * from (select MARKETPLACE_SKU ,NAME ,CATEGORY ,SUB_CATEGORY ,SKUCODE ,row_number() over (partition by lower(marketplace_sku) order by 1) rw from sleepycat_db.maplemonk.final_sku_master ) where rw = 1 ) p on lower(fi.sku) = lower(p.marketplace_sku) left join (select \"order-id\" order_id ,CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', \"purchase-date\":: DATETIME) as Purchase_date ,CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', \"payments-date\":: DATETIME) as Payments_date ,\"buyer-email\" Buyer_email ,\"buyer-name\" Buyer_name ,\"recipient-name\" Recipient_Name from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_orders_fact_items) AmazonOrdersBuyer on fi.order_id=AmazonOrdersBuyer.order_id ; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_fact_items AS SELECT afi.* ,quantity * ifnull(\"Item Quantity Multiplier\",1) as final_mapped_quantity FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_amazon_fact_items_TEMP_Category afi left join(select * from ( select *, row_number() over(partition by sku_code order by end_date) rw from sleepycat_db.maplemonk.sku_mrp_cogs ) where rw=1 )mrp_map on lower(afi.common_sku_code) = lower(mrp_map.sku_code) ;",
